package hu.synostream.android;
import android.app.*;import android.content.*;import android.widget.*;import androidx.test.ext.junit.runners.AndroidJUnit4;import androidx.test.platform.app.InstrumentationRegistry;import androidx.test.uiautomator.*;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import static org.junit.Assert.*;import java.util.*;import java.util.regex.Pattern;
@RunWith(AndroidJUnit4.class) public class Android056Test {
 final Android050FlowTest f=new Android050FlowTest();
 @Before public void init(){f.instrumentation=InstrumentationRegistry.getInstrumentation();f.context=f.instrumentation.getTargetContext();f.app=(SynoApp)f.context.getApplicationContext();f.device=UiDevice.getInstance(f.instrumentation);UiLocale.save(f.context,"hu");}
 @After public void cleanup()throws Exception{UiLocale.save(f.context,"hu");f.instrumentation.runOnMainSync(()->{f.app.cancelScan();f.app.epoch++;f.app.torrentDraft.close();f.app.externalTorrentUri=null;f.app.externalTorrentMime=null;});f.cleanup();}
 void login()throws Exception{f.device.wakeUp();f.device.executeShellCommand("wm dismiss-keyguard");f.device.setOrientationNatural();f.instrumentation.runOnMainSync(()->{f.app.client=null;f.app.demo=false;f.app.busy=false;f.app.page="movies";f.app.libraryDraft=null;f.app.downloadsOpen=false;});f.context.startActivity(new Intent(f.context,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));assertTrue(f.device.wait(Until.hasObject(By.res(f.pkg+":id/login_button")),10000));f.instrumentation.waitForIdleSync();}
 void scrollText(String value)throws Exception{if(f.device.wait(Until.hasObject(By.text(value)),1500))return;new UiScrollable(new UiSelector().scrollable(true)).scrollTextIntoView(value);assertTrue(value,f.device.wait(Until.hasObject(By.text(value)),5000));}
 void switchEnglish()throws Exception{MainActivity a=f.activity();f.instrumentation.runOnMainSync(()->LanguageUi.show(a));f.text("English");assertTrue(f.device.wait(Until.hasObject(By.text("Language: English")),10000));f.instrumentation.waitForIdleSync();}
 @Test public void languagePersistsAndLoginDraftSurvives()throws Exception{login();f.device.findObject(By.res(f.pkg+":id/login_address")).setText("fixture-address");f.device.findObject(By.res(f.pkg+":id/login_user")).setText("fixture-user");f.device.findObject(By.res(f.pkg+":id/login_password")).setText("fixture-password");switchEnglish();assertEquals("fixture-address",f.device.findObject(By.res(f.pkg+":id/login_address")).getText());assertEquals("fixture-user",f.device.findObject(By.res(f.pkg+":id/login_user")).getText());MainActivity a=f.activity();f.instrumentation.runOnMainSync(()->{assertEquals("fixture-password",((EditText)a.findViewById(R.id.login_password)).getText().toString());a.recreate();});assertTrue(f.device.wait(Until.hasObject(By.text("Language: English")),10000));assertEquals("en",UiLocale.language(f.context));assertTrue(f.device.hasObject(By.text("Remember me")));assertFalse(f.device.hasObject(By.text("Emlékezz rám")));scrollText("About");f.text("About");assertTrue(f.device.wait(Until.hasObject(By.text("Version: "+BuildConfig.VERSION_NAME)),10000));assertNotNull(f.device.findObject(By.text("License: GNU GPL-3.0-only")));assertTrue(f.device.takeScreenshot(new java.io.File(f.context.getFilesDir(),"056-about-en.png")));f.click("detail_close");MainActivity b=f.activity();f.instrumentation.runOnMainSync(()->LanguageUi.show(b));f.text("Magyar");assertTrue(f.device.wait(Until.hasObject(By.text("Nyelv: Magyar")),10000));assertEquals("hu",UiLocale.language(f.context));}
 @Test public void aboutLicenseAndRotationWorkOffline()throws Exception{login();scrollText("Névjegy");f.text("Névjegy");assertTrue(f.device.wait(Until.hasObject(By.text("Verzió: "+BuildConfig.VERSION_NAME)),10000));assertNotNull(f.device.findObject(By.text("Copyright © 2026 Lőrincz László")));scrollText("Licenc és jogi tájékoztató");f.text("Licenc és jogi tájékoztató");scrollText("A GPL-3.0 licenc teljes szövege (angol)");f.text("A GPL-3.0 licenc teljes szövege (angol)");assertTrue(f.device.wait(Until.hasObject(By.res(f.pkg+":id/legal_text")),10000));assertTrue(f.device.findObject(By.res(f.pkg+":id/legal_text")).getText().contains("GNU GENERAL PUBLIC LICENSE"));f.device.setOrientationLeft();Thread.sleep(800);assertTrue(f.device.wait(Until.hasObject(By.res(f.pkg+":id/legal_text")),10000));assertEquals("gpl",f.activity().informationPage);f.device.pressBack();assertTrue(f.device.wait(Until.hasObject(By.text("Jogi tájékoztató")),10000));assertEquals("legal",f.activity().informationPage);assertTrue(f.device.takeScreenshot(new java.io.File(f.context.getFilesDir(),"056-legal-hu.png")));}
 @Test public void englishMenuAndCustomDataStayUntouched()throws Exception{try(FakeNas n=new FakeNas()){Library.Card card=new Library.Card("/Movies/Filmek.mkv","Filmek",true);f.setup(n,List.of(card));MainActivity a=f.activity();f.instrumentation.runOnMainSync(()->{try{f.app.libraries.put(new JSONObject().put("id","custom-fixture").put("name","Saját filmek").put("movie",true).put("paths",new JSONArray()).put("builtin",false));}catch(Exception e){throw new RuntimeException(e);}f.app.changed();});UiLocale.save(f.context,"en");f.instrumentation.runOnMainSync(a::recreate);assertTrue(f.device.wait(Until.hasObject(By.text("Movies")),10000));assertTrue(f.device.hasObject(By.desc("Filmek")));assertEquals("Filmek",LibraryConfig.defaultLibrary(f.app.libraries,true).optString("name"));assertTrue(f.device.wait(Until.hasObject(By.desc("More options")),10000));f.device.findObject(By.desc("More options")).click();f.text("Switch display mode");MainActivity current=f.activity();int[] columns={0};long changed=System.currentTimeMillis()+5000;while(System.currentTimeMillis()<changed){f.instrumentation.runOnMainSync(()->columns[0]=((GridView)current.findViewById(R.id.poster_grid)).getNumColumns());if(columns[0]==1)break;Thread.sleep(50);}assertEquals(1,columns[0]);f.click("menu_button");assertTrue(f.device.wait(Until.hasObject(By.text("TV shows")),10000));assertNotNull(f.device.findObject(By.text("Saját filmek")));assertEquals("Filmek",f.app.cards.get(0).title);}}
 @Test public void englishTorrentFlowKeepsSelectionAndNasProtocol()throws Exception{try(FakeNas n=new FakeNas()){f.setup(n,List.of());f.click("menu_button");f.text("Beállítások");switchEnglish();f.device.pressBack();f.context.startActivity(new Intent().setComponent(new ComponentName(f.pkg+".test","hu.synostream.android.FixtureTorrentSender")).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK).putExtra("kind","ok"));assertTrue(f.device.wait(Until.hasObject(By.text("Example.torrent")),10000));f.text("Choose NAS folder");assertTrue(f.device.wait(Until.hasObject(By.text("NAS shares")),10000));f.text("Movies");assertTrue(f.device.wait(Until.hasObject(By.text("/Movies")),10000));f.device.findObject(By.res("android:id/button1")).click();f.text("Add");assertTrue(f.device.wait(Until.hasObject(By.text("release.nfo")),15000));assertTrue(n.torrentRouteValid);assertEquals(0,n.starts);assertTrue(f.device.findObject(By.text("release.nfo")).isChecked());assertFalse(f.device.findObject(By.text("Sample/clip.mkv")).isChecked());f.text("Download selected files");long end=System.currentTimeMillis()+10000;while((n.starts==0||f.app.downloadBusy)&&System.currentTimeMillis()<end)Thread.sleep(50);assertEquals(1,n.starts);assertTrue(n.selectedNfo);assertFalse(n.selectedSample);}}
 @Test public void englishSeriesUsesLocalizedSeasonEpisodeAndAudioLabels()throws Exception{try(FakeNas n=new FakeNas()){Library.Card card=new Library.Card("/Series/First.Show","Saját sorozat",false);f.setup(n,List.of(card));UiLocale.save(f.context,"en");MainActivity a=f.activity();f.instrumentation.runOnMainSync(a::recreate);assertTrue(f.device.wait(Until.hasObject(By.desc(card.title)),10000));f.device.findObject(By.desc(card.title)).click();assertTrue(f.device.wait(Until.hasObject(By.text("OVERVIEW")),10000));f.device.findObject(By.desc("Series episodes")).click();Pattern season=Pattern.compile(".*Season 1");assertTrue(f.device.wait(Until.hasObject(By.text(season)),10000));f.device.findObject(By.text(season)).click();assertTrue(f.device.wait(Until.hasObject(By.text("Episode 1")),10000));MainActivity current=f.activity();f.instrumentation.runOnMainSync(()->{MatroskaAudio.Track track=new MatroskaAudio.Track();track.number=2;track.ordinal=2;track.language="hun";track.codec="A_AC3";assertEquals("Track 2: hun (ac3)",UiText.track(current,track));});assertTrue(f.device.takeScreenshot(new java.io.File(f.context.getFilesDir(),"056-series-en.png")));}}
 Notification notification(NotificationManager manager,String title)throws Exception{long end=System.currentTimeMillis()+5000;Notification result=null;while(System.currentTimeMillis()<end){result=Arrays.stream(manager.getActiveNotifications()).filter(x->x.getId()==41).map(x->x.getNotification()).findFirst().orElse(null);if(result!=null&&title.equals(result.extras.getString(Notification.EXTRA_TITLE)))return result;Thread.sleep(50);}assertNotNull(result);assertEquals(title,result.extras.getString(Notification.EXTRA_TITLE));return result;}
 @Test public void messagesAndActiveNotificationFollowLanguageWithoutStoppingStream()throws Exception{try(FakeNas n=new FakeNas()){f.setup(n,List.of());f.device.executeShellCommand("pm grant "+f.pkg+" android.permission.POST_NOTIFICATIONS");UiLocale.save(f.context,"en");MainActivity a=f.activity();f.instrumentation.runOnMainSync(a::recreate);f.instrumentation.waitForIdleSync();assertEquals("1 title • 1 manual entry • 1 to retry • 1 invalid pairing",UiText.message(f.context,"1 műsor • 1 kézi bejegyzés • 1 újrapróbálandó • 1 hibás párosítás"));assertEquals("2 titles processed…",UiText.message(f.context,"2 műsor feldolgozva…"));assertEquals("The NAS reported an invalid request parameter (101; torrent preparation). The operation was not retried automatically.",UiText.message(f.context,"A NAS érvénytelen kérési paramétert jelzett (101; torrent előkészítése). A műveletet nem ismételtem meg automatikusan."));f.instrumentation.runOnMainSync(()->StreamService.readyUri=null);f.context.startForegroundService(new Intent(f.context,StreamService.class).putExtra("path","/Movies/Demo.Movie.2020.mkv"));long end=System.currentTimeMillis()+7000;while(StreamService.readyUri==null&&System.currentTimeMillis()<end)Thread.sleep(50);assertNotNull(StreamService.readyUri);android.net.Uri before=StreamService.readyUri;NotificationManager manager=f.context.getSystemService(NotificationManager.class);notification(manager,"SynoStream • NAS connection");UiLocale.save(f.context,"hu");LanguageUi.refreshNotifications(f.context);Notification notification=notification(manager,"SynoStream • NAS-kapcsolat");assertEquals("SynoStream • NAS-kapcsolat",notification.extras.getString(Notification.EXTRA_TITLE));assertEquals("Leállítás",notification.actions[0].title.toString());UiLocale.save(f.context,"en");LanguageUi.refreshNotifications(f.context);notification=notification(manager,"SynoStream • NAS connection");assertEquals("SynoStream • NAS connection",notification.extras.getString(Notification.EXTRA_TITLE));assertEquals("Stop",notification.actions[0].title.toString());assertEquals(before,StreamService.readyUri);}}
}
